# ── tests ───────────────────────────────────────────────────────────────────────

using Test

@testset "LRU basics" begin
    @testset "LRU basics" begin
        c = LRU{String, Int}(3)
        @test isempty(c)
        @test length(c) == 0

        c["a"] = 1
        c["b"] = 2
        c["c"] = 3
        @test length(c) == 3
        @test c["a"] == 1
        @test c["b"] == 2
        @test c["c"] == 3
    end

    @testset "LRU eviction" begin
        c = LRU{String, Int}(3)
        c["a"] = 1
        c["b"] = 2
        c["c"] = 3

        # Insert "d" → evicts "a" (least recently used)
        c["d"] = 4
        @test length(c) == 3
        @test !haskey(c, "a")
        @test haskey(c, "b")
        @test haskey(c, "c")
        @test haskey(c, "d")
        @test c["b"] == 2
        @test c["c"] == 3
        @test c["d"] == 4
    end

    @testset "LRU touch on get" begin
        c = LRU{String, Int}(3)
        c["a"] = 1
        c["b"] = 2
        c["c"] = 3
        # "a" is LRU; reading "a" makes it most-recent
        get(c, "a", -1)
        @test c["a"] == 1  # still there
        @test c["b"] == 2
        @test c["c"] == 3
        # Now insert "d" → evicts "b" (new LRU)
        c["d"] = 4
        @test !haskey(c, "b")
        @test haskey(c, "a")
        @test haskey(c, "c")
        @test haskey(c, "d")
    end

    @testset "LRU get with default" begin
        c = LRU{String, Int}(2)
        @test get(c, "x", "MISS") == "MISS"
        c["a"] = 1
        c["b"] = 2
        @test get(c, "a", "MISS") == 1
        @test get(c, "c", "MISS") == "MISS"
    end

    @testset "LRU update existing key" begin
        c = LRU{String, Int}(3)
        c["a"] = 1
        c["b"] = 2
        c["a"] = 99  # update + touch
        @test c["a"] == 99
        @test haskey(c, "a")
        @test length(c) == 3
    end

    @testset "LRU clear" begin
        c = LRU{String, Int}(3)
        c["a"] = 1; c["b"] = 2; c["c"] = 3
        empty!(c)
        @test isempty(c)
        @test length(c) == 0
        @test get(c, "a", 0) == 0
    end

    @testset "LRU iteration order" begin
        c = LRU{String, Int}(5)
        c["a"]=1; c["b"]=2; c["c"]=3; c["d"]=4; c["e"]=5
        # most-recent to least: e d c b a
        ks = collect(keys(c))
        @test ks == ["e","d","c","b","a"]
        vs = collect(values(c))
        @test vs == [5,4,3,2,1]
    end

    @testset "LRU iteration after touch" begin
        c = LRU{String, Int}(3)
        c["a"]=1; c["b"]=2; c["c"]=3
        get(c, "a", 0)  # touch "a"
        ks = collect(keys(c))
        @test ks == ["a","c","b"]  # a most recent, b least recent
    end

    @testset "LRU capacity 1" begin
        c = LRU{Int, String}(1)
        c[1] = "one"; c[1] = "uno"
        @test c[1] == "uno"
        @test length(c) == 1
        c[2] = "two"
        @test !haskey(c, 1)
        @test haskey(c, 2)
        @test c[2] == "two"
    end

    @testset "LRU no-alloc on get" begin
        c = LRU{String, Int}(3)
        c["a"]=1; c["b"]=2; c["c"]=3
        # get on present key must not allocate
        @test @allocated get(c, "b", 0) == 0
        # get on absent key may or may not allocate (dict miss can);
        # we only require the present-key case
    end
end

